def solution(friends, gifts):

    #주고받은 선물
    n=len(friends)
    graph=[[0]*n for _ in range(n)]
    check=[[0]*n for _ in range(n)]
    for left_right in gifts:
        left,right=left_right.split()
        idx_left=friends.index(left)
        idx_right=friends.index(right)
        graph[idx_left][idx_right]+=1
        # 더 많이 줬는지 체크
        check[idx_left][idx_right]+=1
        check[idx_right][idx_left]-=1


    #선물 지수
    dic={}
    for friend in friends:
        if friend not in dic:
            dic[friend]=[0]*2
    ##준선물,받은선물 체크
    for i in range(n):
        for j in range(n):
            if i==j:
                continue
            else:
                if graph[i][j]>0:
                    dic[friends[i]][0]+=graph[i][j]
                    dic[friends[j]][1]+=graph[i][j]

    ##선물지수까지 체크
    final_dic={}
    for key,value in dic.items():
        if key not in final_dic:
            final_dic[key]=value[0]-value[1]

    answer_lst=[0]*n
    for i in range(n):
        for j in range(n):
            if i==j:
                continue
            else:
                if check[i][j]>0:
                    answer_lst[i]+=1
                elif check[i][j]==0:
                    if final_dic[friends[i]]>final_dic[friends[j]]:
                        answer_lst[i]+=1
    answer=max(answer_lst)
    return answer

def solution(friends, gifts):

    # 준 사람 : 받은 사람 [list는 friends 수 만큼 0으로 채워줌] 딕셔너리 생성
    gift_history = {friend : [0 for i in range(len(friends))] for friend in friends}

    # 주고받은 선물
    for gift in gifts:
        giver , receiver = gift.split()
        # 선물 기록에서 receiver 찾아가서 해당 value list에서 getter의 index에 1 추가
        gift_history[giver][friends.index(receiver)] += 1

    # 선물 지수
    # gift_history에서 가로 합 - 세로 합
    gift_point = []
    for giver in friends:
        given = sum(gift_history[giver])
        received = sum(gift_history[receiver][friends.index(giver)] for receiver in friends)
        gift_point.append(given - received)

    # 최종적으로 다음 달에 받을 선물 수 담을 list
    next_month_gift = [0 for i in range(len(friends))]

    # 서로 선물을 주고 받았는지 체크
    for A in range(len(friends)):
        for B in range(A+1, len(friends)):
            num_A_to_B = gift_history[friends[A]][friends.index(friends[B])]
            num_B_to_A = gift_history[friends[B]][friends.index(friends[A])]

            # 두 사람 사이에 더 많은 선물을 준 사람이 다음 달에 선물을 하나 받습니다.
            if num_A_to_B > num_B_to_A:
                next_month_gift[A] += 1
            elif num_A_to_B < num_B_to_A:
                next_month_gift[B] += 1
            # 두 사람이 선물을 주고받은 기록이 하나도 없거나 주고받은 수가 같다면
            else:
                # 선물 지수가 더 큰 사람이 선물 지수가 더 작은 사람에게 선물을 하나 받습니다.
                if gift_point[A] > gift_point[B]:
                    next_month_gift[A] += 1
                elif gift_point[A] < gift_point[B]:
                    next_month_gift[B] += 1
                #  선물 지수마저 같다면 선물을 주고 받지 않는다.
                else:
                    None
    # 다음달에 가장 많은 선물을 받는 친구가 받을 선물의 수
    return max(next_month_gift)

from itertools import combinations

def solution(friends, gifts):
    last_month = {friend: {} for friend in friends}
    for gift in gifts:
        giver, receiver = gift.split()
        if last_month[giver].get(receiver):
            last_month[giver][receiver] += 1
        else:
            last_month[giver][receiver] = 1

    gift_score = {friend: 0 for friend in friends}
    for giver, gift_to in last_month.items():
        for receiver, num in gift_to.items():
            gift_score[giver] += num
            gift_score[receiver] -= num

    this_month = {friend: 0 for friend in friends}
    for a, b in combinations(friends, 2):
        a_to_b = last_month[a].get(b) if last_month[a].get(b) else 0
        b_to_a = last_month[b].get(a) if last_month[b].get(a) else 0
        if a_to_b > b_to_a:
            this_month[a] += 1
        elif a_to_b < b_to_a:
            this_month[b] += 1
        elif gift_score[a] > gift_score[b]:
            this_month[a] += 1
        elif gift_score[b] > gift_score[a]:
            this_month[b] += 1

    return max(this_month.values())

