            is_box[i][j] = 0

        return 0

    def use_crane(alpha):
        # 1. 모든 알파벳 검색 후, 빼주기
        for i in range(n):
            for j in range(m):
                if storage[i][j] == alpha:
                    is_box[i][j] = 0
        return 0

    def get_outside_contact(alpha):
        # 효율 생각 안하고, BFS

        # (n+2)x(m+2) 확장격자에서 (0,0) 바깥공기부터 BFS
        visited = [[False] * (m + 2) for _ in range(n + 2)]

        q = deque([(0, 0)])
        visited[0][0] = True

        outside_targets = set()

        # 외부 라운드 에서부터 색칠해 나간다고 생각하면 편함.
        while q:
            x, y = q.popleft()

            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x + dx, y + dy

                # 격자 범위 외부 이거나, 방문 했으면 건너 뛰기
                if (not (0 <= nx <= n + 1 and 0 <= ny <= m + 1)) or visited[nx][ny]:
                    continue

                # 방문 처리
                visited[nx][ny] = True

                # 1. 내부라면?
                if 1 <= nx <= n and 1 <= ny <= m:
                    # 실제 창고 내부 좌표로 치환
                    i, j = nx - 1, ny - 1

                    # Box가 빠진 영역이라면, 색칠 & 계속 이동
                    if is_box[i][j] == 0:
                        q.append((nx, ny))
                    # is_box[i][j] == 1: 막혀 있다면, 색칠 X
                    else:
                        # 단, 알파벳이 alpha면 '외부 접촉이며, 뺄 알파벳' 후보에 추가
                        if storage[i][j] == alpha:
                            outside_targets.add((i, j))
                # 2. 확장격자 바깥(진짜 외부 공기)면, 색칠 & 계속 이동
                else:
                    q.append((nx, ny))

        return outside_targets

    for request in requests:
        # 지게차 [외부 연결만]
        if len(request) == 1:
            use_forklift(request)
        # 크레인 [모두]
        else:
            use_crane(request[0])

    return sum(map(sum, is_box))

def solution(edges):
    def count_edges(edges):
        edge_counts = {}
        for a, b in edges:
            # 각 노드별로 간선의 수를 추가할 딕셔너리를 생성 - 키 존재 여부를 확인해 딕셔너리의 키 값 추가
            if a not in edge_counts:
                edge_counts[a] = [0, 0]
            if b not in edge_counts:
                edge_counts[b] = [0, 0]

            # output edge와 input edge의 개수를 추가
            edge_counts[a][0] += 1  # a는 n번 노드에서 나가는 간선
            edge_counts[b][1] += 1  # b는 n번 노드로 들어오는 간선
        return edge_counts

    def check_answer(edge_counts):
        answer = [0, 0, 0, 0]
        for key, counts in edge_counts.items():
            # 생성된 정점의 번호 확인
            if counts[0] >= 2 and counts[1] == 0:
                answer[0] = key
            # 막대 모양 그래프의 수 확인
            elif counts[0] == 0 and counts[1] > 0:
                answer[2] += 1
            # 8자 모양 그래프의 수 확인
            elif counts[0] >= 2 and counts[1] >= 2:
                answer[3] += 1
        # 도넛 모양 그래프의 수 확인
        answer[1] = (edge_counts[answer[0]][0] - answer[2] - answer[3])

        return answer

    edge_counts = count_edges(edges)
    answer = check_answer(edge_counts)

    return answer

