    for r in records:
        t, n, s = r.split()
        t = int(t[:2]) * 60 + int(t[3:])
        dic[n].append((t, -1 if s == 'IN' else 1))
    keys = dic.keys()
    for key in keys:
        time = 0
        if len(dic[key]) % 2 == 1:
            time += 1439
        for t, s in dic[key]:
            time += t * s
        total_times[key] = time

    result = []
    for key in keys:
