import math

def solution(w,h):
    answer = 0
    all = w * h
    x, y = w, h # x는 최대 공약수
    while y:
        x, y = y, x % y
    # 수학을 이용한 간편한 풀이
    # answer = (w//x - 1) + (h//x - 1) + 1
    # return all - answer * x
    if w == h:
        return all - w
    elif h > w:
        for i in range(w // x):
            answer += math.ceil(h*(i+1)/w) - int(h * i / w)
    else:
        for i in range(h // x):
            answer += math.ceil(w*(i + 1)/h) - int(w * i / h)

    return all - answer * x

