from itertools import combinations

def solution(relation):
    col, row = len(relation), len(relation[0])
    cases = [j for i in range(1, row + 1) for j in combinations(range(row), i)]

    unique = []
    for case in cases:
        tmp = [tuple(r[num] for num in case) for r in relation]
        if len(set(tmp)) == col: unique.append(case)

    minimality = set(unique[:])
    for i in range(len(unique) - 1):
        for j in range(i + 1, len(unique)):
            if len(unique[i]) == len(set(unique[i]).intersection(unique[j])):
                minimality.discard(unique[j])

    return len(minimality)

import itertools

def solution(relation):
    answer = []
    row_count, col_count = len(relation), len(relation[0])

    def check_candidate_key(comb):
        tuples = set()
        for info in relation:
            tuples.add(tuple([info[idx] for idx in comb]))
        if len(tuples) == row_count:
            for ans in answer:
                if len(comb - ans) == len(comb) - len(ans):
                    break
            else:
                answer.append(comb)

    for num in range(1, col_count + 1):
        for comb in itertools.combinations(range(col_count), num):
            check_candidate_key(set(comb))
    return len(answer)

