    #(예외처리) cache의 크기가 0인 경우, 모두 cache miss로 처리한다.(ex 입출력 예제 6번)
    if(cacheSize==0):
        return len(cities)*5

    cache=[cities.pop().lower()]
    #도시이름 배열의 길이만큼 반복
    for x in range(len(cities)+1):
        if not cities:
            return answer
        # cache hit
        i=cities[-1].lower()
        if i in cache:
            answer+=1
            cache.remove(i)
            cache.append(cities.pop().lower())
        #cache miss
        else:
            if(len(cache)==cacheSize):
                cache.pop(0)    # (=) del cache[0]
            cache.append(cities.pop().lower())
            answer+=5

    return answer

def solution(cacheSize, cities):
    answer = 0
    cache = []

    for city in cities:
        city = city.lower()
        if city in cache:
            cache.remove(city)
            cache.append(city)
            answer += 1
        else:
            cache.append(city)
            if len(cache) > cacheSize:
                del cache[0]
            answer += 5
    return answer

def solution(m, n, b, c1=0, c2=0):
    b = [[[v, True] for v in reversed(r)] for r in zip(*b)]

    while (c1 := c2) != (c2 := sum([len(r) for r in b])):
        for r1, r2 in zip(b[:-1], b[1:]):
            for e1, e2, e3, e4 in zip(r1[:-1], r1[1:], r2[:-1], r2[1:]):
                if e1[0] == e2[0] == e3[0] == e4[0]:
                    e1[1] = e2[1] = e3[1] = e4[1] = False

        b = [list(filter(lambda x: x[1], r)) for r in b]

    return m * n - c2

def solution(m, n, board):
    dx, dy = (0, 0, 1, 1), (0, 1, 1, 0)
    answer = 0
    game_board = [[letter for letter in line] for line in board]
    while True:
        # (1) 2X2 형태로 없어지는 블록의 위치 찾기
        eliminate_idx = []
        for row in range(m - 1):
            for col in range(n - 1):
                if game_board[row][col] != '*':
                    now_block = game_board[row][col]
                    for i in range(1, 4):
                        new_row, new_col = row + dx[i], col + dy[i]
                        if now_block != game_board[new_row][new_col]: break
                    else:
                        eliminate_idx.append((row, col))
        if not len(eliminate_idx):
            return answer
        # (2) 블록 제거
        for idx in eliminate_idx:
            r, c = idx
            for i in range(4):
                new_r, new_c = r + dx[i], c + dy[i]
                if game_board[new_r][new_c] != '*':
                    game_board[new_r][new_c] = '*'
                    answer += 1
        # (3) 블록 떨어뜨린 후 새로운 게임판에 넣기
        new_game_board = [['*'] * n for _ in range(m)]
        col_idx = 0
        for vertical_line in zip(*game_board):
            vertical_line, pop_idx, idx = list(vertical_line), [], 0
            for block in vertical_line:
                if block == '*':
                    pop_idx.append(idx)
                idx += 1
            for p_idx in reversed(pop_idx):
                vertical_line.pop(p_idx)
            for _ in range(len(pop_idx)):
                vertical_line.insert(0, '*')
            for row_idx in range(m):
                new_game_board[row_idx][col_idx] = vertical_line[row_idx]
            col_idx += 1
        game_board = new_game_board

