                    tmp.add((i,j))
                    tmp.add((i+1,j))
                    tmp.add((i,j+1))
                    tmp.add((i+1,j+1))
        if len(tmp)==0: return answer # 지워질 블록이 없는 경우 -> 게임 끝
        answer+=len(tmp) # 회당 지워질 블록의 개수 카운팅

        # 지워질 블록의 위치를 0으로 할당
