import re

def solution(str1, str2):
    s1 = [str1[i:i+2].lower() for i in range(len(str1) - 1) if re.findall('[a-z]{2}', str1[i:i+2].lower())]
    s2 = [str2[i:i+2].lower() for i in range(len(str2) - 1) if re.findall('[a-z]{2}', str2[i:i+2].lower())]            

    intersection = sum((Counter(s1) & Counter(s2)).values())
    union = sum((Counter(s1) | Counter(s2)).values())

    if union == 0:
        return 65536

    return int((intersection / union) * 65536)

def solution(str1, str2):
    answer = 0
    def transform(cluster):
        ret=[]
        for i in range(1,len(cluster)):
            a=cluster[i-1]+cluster[i]
            if a.isalpha():
                ret.append(a)
        return ret
    str1,str2=transform(str1.lower()),transform(str2.lower())
    intersection=[]
    for s in str1:
        if s in str2:
            str2.remove(s)
            intersection.append(s)
    union=str1+str2
    if len(union)==0:
        return 65536
    answer=int((len(intersection)/len(union))*65536)
    return answer

