def solution(N, road, K):
    q = []
    INF = int(1e9)
    graph = [[] for _ in range(N + 1)]
    for a, b, c in road:
        graph[a].append((b, c))
        graph[b].append((a, c))

    dist = [INF] * (N + 1)
    dist[1] = 0
    heapq.heappush(q, (0, 1))
    while q:
        cur_time, cur_idx = heapq.heappop(q)
        if dist[cur_idx] < cur_time:
