def solution(maps):
    n = len(maps)
    m = len(maps[0])
    stack = [(0, 0, 1)] # 현재 있는곳도 카운트
    save = []
    move = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while True:
        if not stack:
            if not save:
                return -1
            stack, save = save, stack
        y, x, cost = stack.pop()
        for dy, dx in move:
            ny, nx = y + dy, x + dx
            if 0 <= ny < n and 0 <= nx < m:
                if maps[ny][nx] == 1 or maps[ny][nx] > cost + 1: # 첫 방문 또는 현재 방문이 저비용
                    maps[ny][nx] = cost + 1
                    if ny == n - 1 and nx == m - 1:
                        return cost + 1
                    save.append((ny, nx, cost + 1))

from collections import deque

def solution(maps):
    answer = 0
    ROW = len(maps)
    COL = len(maps[0])
    check_maps = [[False for _ in range(COL)] for _ in range(ROW)]

    def available(x, y):
        return 0 <= x < ROW and 0 <= y < COL

    def bfs(x, y):
        count = 1
        dxy = [(-1, 0), (1, 0), (0, 1), (0, -1)]
        queue = deque([[x, y, count]])
        check_maps[x][y] = True
        while queue:
            x, y, count = queue.popleft()
            if x == ROW - 1 and y == COL - 1:
                return count
            for dx, dy in dxy:
                new_x, new_y = x + dx, y + dy
                if available(new_x, new_y) and not check_maps[new_x][new_y]:
                    if maps[new_x][new_y] == 1:
                        queue.append([new_x, new_y, count + 1])
                        check_maps[new_x][new_y] = True
        return -1

    return bfs(0, 0)

from collections import deque

def solution(maps):
    n, m = len(maps), len(maps[0])

    # 상하좌우에 대한 directions 도 정의 (for 문으로 모두 탐색할 거임)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # deque 사용 -> x,y 넣어줘야하고, 그리고 거리도 넣어줘야 됨.
    queue = deque([(0, 0, 1)])

    # 방문 기록
    visited = [[False] * m for _ in range(n)]

    def bfs():
        while queue:
            x, y, distance = queue.popleft()

            # 목적지 도착하면 끝.
            if x == n-1 and y == m-1:
                return distance

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                # 범위 확인, 길 확인, 방문 확인
                if 0 <= nx < n and 0 <= ny < m and maps[nx][ny] == 1 and not visited[nx][ny]:
                    queue.append((nx, ny, distance + 1))
                    visited[nx][ny] = True

        return -1

    return bfs()

from itertools import permutations

def solution(baseball):
    digit = [str(i) for i in range(1, 10)]
    candidate = set(map(''.join, permutations(digit, 3)))
    for game in baseball:
        number, strike, ball = game
        number = str(number)

        remove_set = set()
        for cand in candidate:
            temp_strike, temp_ball = 0, 0
            for i in range(3):
                if number[i] == cand[i]: temp_strike += 1
                elif number[i] in cand: temp_ball += 1
            if temp_strike != strike or temp_ball != ball:
                remove_set = remove_set.union([cand])
        candidate = candidate.difference(remove_set)
    return len(candidate)

import numpy as np
from itertools import combinations

def solution(dice):
    def add_dice(x, y):
        return (x[..., None] + y[None, ...]).reshape(-1,)

    def subtract_dice(x, y):
        return x[..., None] - y[None, ...]

    def recursive_add_dice(indices):
        out = dice[indices[0]]
        for j in indices[1:]:
            out = add_dice(out, dice[j])
        return out

    def get_indices2(indices1):
        return tuple([k for k in range(len(dice)) if k not in indices1])

    dice = np.array(dice)
    max_wins = 0
    wins_dict = dict()
    for indices1 in combinations(range(len(dice)), len(dice)//2):
        indices2 = get_indices2(indices1)
        if (indices2, indices1) in wins_dict:
            continue

        sum1 = recursive_add_dice(indices1)
        sum2 = recursive_add_dice(indices2)
        diff = subtract_dice(sum1, sum2)
        wins1 = np.sum(diff > 0)
        wins2 = np.sum(diff < 0)
        wins_dict[(indices1, indices2)] = (wins1, wins2)
        wins_dict[(indices2, indices1)] = (wins2, wins1)

        if wins1 > max_wins:
            max_wins = wins1
            best_indices = indices1
        if wins2 > max_wins:
            max_wins = wins2
            best_indices = indices2
    return [i + 1 for i in best_indices]

from itertools import combinations

def solution(dice):
    answer = []
    max_win = 0
    for comb in combinations(range(len(dice)), len(dice) // 2):
        dices_a = [i for i in comb]
        dices_b = [i for i in range(len(dice)) if i not in comb]

        # a 주사위 세트의 합 빈도 구하기
        first_dice_a = dice[dices_a[0]]
        sums_count_a = {}
        for dice_num in first_dice_a:
            if sums_count_a.get(dice_num):
                sums_count_a[dice_num] += 1
            else:
                sums_count_a[dice_num] = 1
        for dice_idx in dices_a[1:]:
            dice_nums = dice[dice_idx]
            updated_sums_count = {}
            for dice_num in dice_nums:
                for prev_sum in sums_count_a.keys():
                    if updated_sums_count.get(prev_sum + dice_num):
                        updated_sums_count[prev_sum + dice_num] += sums_count_a[prev_sum]
                    else:
                        updated_sums_count[prev_sum + dice_num] = sums_count_a[prev_sum]
            sums_count_a = updated_sums_count

        # b 주사위 세트의 합 빈도 구하기
        first_dice_b = dice[dices_b[0]]
        sums_count_b = {}
        for dice_num in first_dice_b:
            if sums_count_b.get(dice_num):
                sums_count_b[dice_num] += 1
            else:
                sums_count_b[dice_num] = 1
        for dice_idx in dices_b[1:]:
            dice_nums = dice[dice_idx]
            updated_sums_count = {}
            for dice_num in dice_nums:
                for prev_sum in sums_count_b.keys():
                    if updated_sums_count.get(prev_sum + dice_num):
                        updated_sums_count[prev_sum + dice_num] += sums_count_b[prev_sum]
                    else:
                        updated_sums_count[prev_sum + dice_num] = sums_count_b[prev_sum]
            sums_count_b = updated_sums_count

        # a 주사위 세트의 승패 결과 계산
        win = tie = lose = 0
        for sum_a, count_a in sums_count_a.items():
            for sum_b, count_b in sums_count_b.items():
                count = count_a * count_b
                if sum_a > sum_b:
                    win += count
                elif sum_a == sum_b:
                    tie += count
                else:
                    lose += count

        # max_count와 비교하여 업데이트
        if win > max_win:
            answer = [i + 1 for i in dices_a]
            max_win = win

    return answer

def solution(n, tops):
    full = [0] * n
    not_full = [0] * n

    if tops[0] == 1:
        full[0], not_full[0] = 4, 3
    else:
        full[0], not_full[0] = 3, 2

    for i in range(1, n):
        if tops[i] == 1:
            full[i] = (full[i-1] * 3 + not_full[i-1] * 1) % 10007
            not_full[i] = (full[i-1] * 2 + not_full[i-1]) % 10007
        else:
            full[i] = (full[i-1] * 2 + not_full[i-1]) % 10007
            not_full[i] = (full[i-1] + not_full[i-1]) % 10007

    return full[n-1]

