def solution(alp, cop, problems):
    INF = 10**9
    max_alp, max_cop = 0, 0
    for a, c, _, _, _ in problems:
        max_alp, max_cop = max(max_alp, a), max(max_cop, c)
    alp, cop = min(alp, max_alp), min(cop, max_cop)
    dp = [[INF] * (max_cop + 1) for _ in range(max_alp + 1)]
    dp[alp][cop] = 0
    for i in range(alp, max_alp + 1):
        for j in range(cop, max_cop + 1):
            dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1 if i > alp else INF, dp[i][j - 1] + 1 if j > cop else INF)

            for alp_req, cop_req, alp_rwd, cop_rwd, cost in problems:
                if i >= alp_req and j >= cop_req:
                    next_alp, next_cop = min(i + alp_rwd, max_alp), min(j + cop_rwd, max_cop)
                    dp[next_alp][next_cop] = min(dp[next_alp][next_cop], dp[i][j] + cost)
    return dp[-1][-1]

def solution(alp, cop, problems):
    max_alp, max_cop = 0, 0
    for a, c, _, _, _ in problems:
        max_alp, max_cop = max(max_alp, a), max(max_cop, c)
    alp, cop = min(alp, max_alp), min(cop, max_cop)
    INF = float('inf')
    dp = [[INF] * (max_cop + 1) for _ in range(max_alp + 1)]
    dp[alp][cop] = 0
    for i in range(alp, max_alp + 1):
        for j in range(cop, max_cop + 1):
            dp[i][j] = min(dp[i][j], dp[i - 1][j] + 1 if i - 1 >= alp else INF, dp[i][j - 1] + 1 if j - 1 >= cop else INF)

            for alp_req, cop_req, alp_rwd, cop_rwd, cost in problems:
                if i >= alp_req and j >= cop_req:
                    next_alp, next_cop = min(max_alp, i + alp_rwd), min(max_cop, j + cop_rwd)
                    dp[next_alp][next_cop] = min(dp[next_alp][next_cop], dp[i][j] + cost)
    return dp[-1][-1]

def solution(board, aloc, bloc):
    def dfs(board, a, b, turn, count):
        n, m = len(board), len(board[0])
        flag = True
        r1, c1 = a
        r2, c2 = b
        winner, loser = [], []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if turn:
                nr1, nc1 = r1 + dr, c1 + dc
                if 0 <= nr1 < n and 0 <= nc1 < m and board[r1][c1] == 1 and board[nr1][nc1] == 1:
                    flag = False
                    board[r1][c1] = 0
                    cnt, whoWin = dfs(board, [nr1, nc1], b, False, count + 1)
                    if whoWin:
                        winner.append(cnt)
                    else:
                        loser.append(cnt)
                    board[r1][c1] = 1
            else:
                nr2, nc2 = r2 + dr, c2 + dc
                if 0 <= nr2 < n and 0 <= nc2 < m and board[r2][c2] == 1 and board[nr2][nc2] == 1:
                    flag = False
                    board[r2][c2] = 0
                    cnt, whoWin = dfs(board, a, [nr2, nc2], True, count + 1)
                    if whoWin:
                        loser.append(cnt)
                    else:
                        winner.append(cnt)
                    board[r2][c2] = 1
        if flag:
            return (count, not turn)
        else:
            if winner:
                return (min(winner), turn)
            else:
                return (max(loser), not turn)

    return dfs(board, aloc, bloc, True, 0)[0]

def solution(board, skill):
    n, m = len(board), len(board[0])
    arr = [[0] * (m + 1) for _ in range(n + 1)]
    for t, r1, c1, r2, c2, degree in skill:
        arr[r1][c1] += -degree if t == 1 else degree
        arr[r1][c2 + 1] += degree if t == 1 else -degree
        arr[r2 + 1][c1] += degree if t == 1 else -degree
        arr[r2 + 1][c2 + 1] += -degree if t == 1 else degree

    answer = 0
    for i in range(n):
        for j in range(1, m + 1):
            arr[i][j] += arr[i][j - 1]
    for i in range(1, n + 1):
        for j in range(m):
            arr[i][j] += arr[i - 1][j]
    for i in range(n):
        for j in range(m):
            if board[i][j] + arr[i][j] > 0:
                answer += 1
    return answer

