                for u in dp(t,N):
                    if s + u != 0:
                        memo[times].add(s + u)
                    if s - u != 0:
                        memo[times].add(s - u)
                    if s // u != 0:
                        memo[times].add(s // u)
                    if s * u != 0:
                        memo[times].add(s * u)        
        return memo[times]

    dp(8,N)

    for key, value in sorted(memo.items()):
        if number in value:
            return key
    return -1

